dayCol.shortHeading.textContent = lazy.l10n.formatValueSync("day-header", {
  dayName: dateFormatter.shortWeekdayNames[dayDate.weekday],
  dayIndex: dateFormatter.formatDateWithoutYear(dayDate),
});
